(6360758, 941807, 30982, '<td valign="top">Wonderful textures and natural framing.  Very pleasing.</td>', 'Wonderful textures and natural framing.  Very pleasing.', '2011-03-23 01:20:52.000000', NULL, 1),
(6360760, 941234, 30982, '<td valign="top">Excellent color coordination!  Great pose as well.</td>', 'Excellent color coordination!  Great pose as well.', '2011-03-23 01:21:47.000000', NULL, 1),
