(6361013, 942095, 15711, '<td valign="top">Oh this is delicious!  Deep and moody.  I like it. :)</td>', 'Oh this is delicious!  Deep and moody.  I like it. :)', '2011-03-23 08:45:59.000000', NULL, 1),
