(6361112, 942242, 50641, '<td valign="top">I know it''s tough in basic editing to make them show up but there are a few tricks that are legal.  That said, I kind of enjoyed having to look hard at this just to find them - the subtlety and the curvy puzzle pieces are kinda fun.</td>', 'I know it''s tough in basic editing to make them show up but there are a few tricks that are legal.  That said, I kind of enjoyed having to look hard at this just to find them - the subtlety and the curvy puzzle pieces are kinda fun.', '2011-03-23 10:16:34.000000', NULL, 1),
(6361114, 941892, 50641, '<td valign="top">like the opposing palm fronds</td>', 'like the opposing palm fronds', '2011-03-23 10:17:19.000000', NULL, 1),
(6361115, 941980, 50641, '<td valign="top">very good that you got his head, i have so many pictures of vulture butts</td>', 'very good that you got his head, i have so many pictures of vulture butts', '2011-03-23 10:17:50.000000', NULL, 1),
