(6361204, 941518, 65234, '<td valign="top">Great timing on the capture and very pretty bird.</td>', 'Great timing on the capture and very pretty bird.', '2011-03-23 11:28:21.000000', NULL, 1),
(6361205, 941220, 65234, '<td valign="top">Nest building time!  Lovely translucence in the wings.</td>', 'Nest building time!  Lovely translucence in the wings.', '2011-03-23 11:28:30.000000', NULL, 1),
(6361208, 942013, 65234, '<td valign="top">Ick, but wonderfully well captured, and the setting just takes this to a whole ''nother level of storytelling!</td>', 'Ick, but wonderfully well captured, and the setting just takes this to a whole ''nother level of storytelling!', '2011-03-23 11:28:41.000000', NULL, 1),
(6361209, 941660, 65234, '<td valign="top">Really interesting setting for these two.  The birds are the subject, yet there is so much more to look at and enjoy.</td>', 'Really interesting setting for these two.  The birds are the subject, yet there is so much more to look at and enjoy.', '2011-03-23 11:28:51.000000', NULL, 1),
(6361210, 941933, 65234, '<td valign="top">But lovely chaos.  I like the pastels of the sunset, the moon up in the corner, and the many flying gulls in various poses and degrees of motion blur.</td>', 'But lovely chaos.  I like the pastels of the sunset, the moon up in the corner, and the many flying gulls in various poses and degrees of motion blur.', '2011-03-23 11:29:00.000000', NULL, 1),
(6361211, 941075, 65234, '<td valign="top">Nicely captured sense of motion here.</td>', 'Nicely captured sense of motion here.', '2011-03-23 11:29:08.000000', NULL, 1),
(6361212, 941022, 65234, '<td valign="top">Nice combination of sharpness and motion blur.</td>', 'Nice combination of sharpness and motion blur.', '2011-03-23 11:29:19.000000', NULL, 1),
(6361213, 941927, 65234, '<td valign="top">Run away, run away!  Or fly away, I guess ;-)  Very interesting scene with a lot of action in it.</td>', 'Run away, run away!  Or fly away, I guess ;-)  Very interesting scene with a lot of action in it.', '2011-03-23 11:29:27.000000', NULL, 1),
(6361215, 941435, 65234, '<td valign="top">Wonderful assortment of poses.  I particularly like the gull who appears to be hovering and looking at me with his head cocked to one side, and the Grebes ignoring their nosy neighbors.</td>', 'Wonderful assortment of poses.  I particularly like the gull who appears to be hovering and looking at me with his head cocked to one side, and the Grebes ignoring their nosy neighbors.', '2011-03-23 11:29:39.000000', NULL, 1),
(6361216, 941880, 65234, '<td valign="top">Those big feet hanging down do not look aerodynamic!  Cute Pelican face.  A tad soft looking to me but very nice shot.</td>', 'Those big feet hanging down do not look aerodynamic!  Cute Pelican face.  A tad soft looking to me but very nice shot.', '2011-03-23 11:29:46.000000', NULL, 1),
(6361217, 941443, 65234, '<td valign="top">Elegant and graceful.  Love the soft focus and the gentle light.</td>', 'Elegant and graceful.  Love the soft focus and the gentle light.', '2011-03-23 11:29:59.000000', NULL, 1),
(6361218, 942176, 65234, '<td valign="top">Classic image.  I can just see a bit of catchlight in the eye as the bird looks off in the distance; the photographer was clearly not of interest at this moment.</td>', 'Classic image.  I can just see a bit of catchlight in the eye as the bird looks off in the distance; the photographer was clearly not of interest at this moment.', '2011-03-23 11:30:07.000000', NULL, 1),
(6361219, 942240, 65234, '<td valign="top">Stop action on a Hummingbird is quite a feat!  Scene is a bit busy; if it was possible to use a shallower DOF I would have.  But I''m still impressed with the capture.</td>', 'Stop action on a Hummingbird is quite a feat!  Scene is a bit busy; if it was possible to use a shallower DOF I would have.  But I''m still impressed with the capture.', '2011-03-23 11:30:17.000000', NULL, 1),
(6361220, 941234, 65234, '<td valign="top">Like the limited palette here, and the combination of sharpness and motion blur in the goose.</td>', 'Like the limited palette here, and the combination of sharpness and motion blur in the goose.', '2011-03-23 11:30:24.000000', NULL, 1),
(6361250, 941735, 129278, '<td valign="top">looks great - really easy on the eyes</td>', 'looks great - really easy on the eyes', '2011-03-23 11:48:04.000000', NULL, 1),
(6361256, 941923, 73942, '<td valign="top">I can honestly say I''ve never seen a pigeon shot like this, I love the wings.</td>', 'I can honestly say I''ve never seen a pigeon shot like this, I love the wings.', '2011-03-23 11:56:23.000000', NULL, 1),
(6361324, 942240, 107603, '<td valign="top">I really like this. Beautiful colours</td>', 'I really like this. Beautiful colours', '2011-03-23 13:17:10.000000', NULL, 1),
(6361353, 942013, 115307, '<td valign="top">Wow, awesome capture. I didn''t even know that herons ate anything other than fish.<br/>The graveyard is pretty distracting, but its not like you could decide where he was going to fly with his prize. Hope this does well for you. 8</td>', 'Wow, awesome capture. I didn''t even know that herons ate anything other than fish.The graveyard is pretty distracting, but its not like you could decide where he was going to fly with his prize. Hope this does well for you. 8', '2011-03-23 13:48:32.000000', NULL, 1),
(6361355, 942114, 115307, '<td valign="top">Interesting editing choice, but I actually quite like the result. It gives the wings a great texture. 7</td>', 'Interesting editing choice, but I actually quite like the result. It gives the wings a great texture. 7', '2011-03-23 13:49:30.000000', NULL, 1),
(6361429, 941119, 123825, '<td valign="top">Nice detail!</td>', 'Nice detail!', '2011-03-23 15:40:24.000000', NULL, 1),
