(6361718, 941515, 129091, '<td valign="top">Nice image!</td>', 'Nice image!', '2011-03-23 19:24:11.000000', NULL, 1),
(6361721, 941443, 129091, '<td valign="top">Although the bird is flying it feels more like it is swimming in the ocean.  I like the bluegreen background!</td>', 'Although the bird is flying it feels more like it is swimming in the ocean.  I like the bluegreen background!', '2011-03-23 19:25:01.000000', NULL, 1),
(6361748, 942128, 26464, '<td valign="top">awesome</td>', 'awesome', '2011-03-23 19:42:08.000000', NULL, 1),
(6361753, 942242, 26464, '<td valign="top">man had to look twice here... wow!</td>', 'man had to look twice here... wow!', '2011-03-23 19:43:30.000000', NULL, 1),
(6361846, 941565, 772, '<td valign="top">This is really an excellent image.  The composition is fantastic and that''s nicely highlighted by the bird looking in your direction for the shot.  It also makes a nice black and white, and would be even stronger if the background was a bit darker to really set the bird off against it.  This photo is one of my top ten in this challenge... good luck :)</td>', 'This is really an excellent image.  The composition is fantastic and that''s nicely highlighted by the bird looking in your direction for the shot.  It also makes a nice black and white, and would be even stronger if the background was a bit darker to really set the bird off against it.  This photo is one of my top ten in this challenge... good luck :)', '2011-03-23 20:59:45.000000', NULL, 1),
(6361854, 941895, 772, '<td valign="top">This is a cute photo.  It even has a bird in flight.  However, that bird in flight is not the focal point of the image and it probably should be where birds in flight is the theme of the challenge.</td>', 'This is a cute photo.  It even has a bird in flight.  However, that bird in flight is not the focal point of the image and it probably should be where birds in flight is the theme of the challenge.', '2011-03-23 21:03:36.000000', NULL, 1),
