(6365863, 942219, 37392, '<td valign="top">great focus!!!!</td>', 'great focus!!!!', '2011-03-28 23:26:32.000000', NULL, 1),
(6365876, 942069, 100831, '<td valign="top">pretty!</td>', 'pretty!', '2011-03-28 23:47:31.000000', NULL, 1),
(6365903, 942171, 772, '<td valign="top">Nice capture of the mallard in flight here... The water spray and the slight motion on the wings creates a good sense of action in this photograph.  You also managed to be in the right position to catch this duck in excellent sunlight which helped out tremendously for the color.  <br/> <br/>As for the composition, I believe this might have been a great image for a square crop rather than vertical.  Since the action is moving left to right, the unused space at the bottom of the frame becomes slightly irrelevant in the greater scheme of things.  A square crop with the duck in the center of the frame would work well here because the duck itself would create opposing diagonals with the body and wings in their positions of flight.  Just some food for thought :)</td>', 'Nice capture of the mallard in flight here... The water spray and the slight motion on the wings creates a good sense of action in this photograph.  You also managed to be in the right position to catch this duck in excellent sunlight which helped out tremendously for the color.   As for the composition, I believe this might have been a great image for a square crop rather than vertical.  Since the action is moving left to right, the unused space at the bottom of the frame becomes slightly irrelevant in the greater scheme of things.  A square crop with the duck in the center of the frame would work well here because the duck itself would create opposing diagonals with the body and wings in their positions of flight.  Just some food for thought :)', '2011-03-29 00:44:06.000000', NULL, 1),
(6365910, 941218, 124256, '<td valign="top">It would have been really awesome if the other goose didn''t muddy up the primary''s feet and tail.  As it is, nice shot!</td>', 'It would have been really awesome if the other goose didn''t muddy up the primary''s feet and tail.  As it is, nice shot!', '2011-03-29 00:59:22.000000', NULL, 1),
(6365911, 941437, 124256, '<td valign="top">Very pretty.  I love the lighting and the angle.  I really don''t like the crop.  Personally I''d prefer to have much more sky to the right of the subject plus either above or below.  As it is, I don''t think it works dead center, and I don''t like each wingtip barely clipped.</td>', 'Very pretty.  I love the lighting and the angle.  I really don''t like the crop.  Personally I''d prefer to have much more sky to the right of the subject plus either above or below.  As it is, I don''t think it works dead center, and I don''t like each wingtip barely clipped.', '2011-03-29 00:59:36.000000', NULL, 1),
(6365914, 941009, 124256, '<td valign="top">Nice idea.  Somehow I think the particular bird (maybe the species or position) doesn''t lend itself to this soft overexposed dreaminess.  I think it''s the apparently tiny head with huge eye.</td>', 'Nice idea.  Somehow I think the particular bird (maybe the species or position) doesn''t lend itself to this soft overexposed dreaminess.  I think it''s the apparently tiny head with huge eye.', '2011-03-29 01:01:20.000000', NULL, 1),
(6365915, 941234, 124256, '<td valign="top">Neat shot.  I wish the head wasn''t in shadow.</td>', 'Neat shot.  I wish the head wasn''t in shadow.', '2011-03-29 01:01:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6365916, 941400, 124256, '<td valign="top">Neat shot!  It''s awesome to have a m/f pair -- and for their wings to be in the same position with matching body posture.  Cool!</td>', 'Neat shot!  It''s awesome to have a m/f pair -- and for their wings to be in the same position with matching body posture.  Cool!', '2011-03-29 01:02:38.000000', NULL, 1),
(6365917, 941075, 124256, '<td valign="top">Cool.  The thick dark line at the waterline is too strong/dominant.  Otherwise, really nice motion blur and composition.  I wish highlights were more dramatic.</td>', 'Cool.  The thick dark line at the waterline is too strong/dominant.  Otherwise, really nice motion blur and composition.  I wish highlights were more dramatic.', '2011-03-29 01:04:17.000000', NULL, 1),
(6365918, 942024, 124256, '<td valign="top">I love the bird.  It''s gorgeous and pops.  I don''t really like anything else about the shot though.  Given the background you have, I feel like the bird needs to be much brighter or something.  But, focusing on the bird, I don''t want it to be brighter or anything.  Maybe I''d like it more with a tighter crop.</td>', 'I love the bird.  It''s gorgeous and pops.  I don''t really like anything else about the shot though.  Given the background you have, I feel like the bird needs to be much brighter or something.  But, focusing on the bird, I don''t want it to be brighter or anything.  Maybe I''d like it more with a tighter crop.', '2011-03-29 01:04:38.000000', NULL, 1),
(6365923, 941895, 124256, '<td valign="top">There''s way too much going on in the background.  People on the bench looking this way, colorful dragons (or whatever), lots of lights, railings, umbrellas, and so on.  I wish all that stuff was out of focus, reducing them to oblivion.  Instead I just find them very distracting.  I love the kid and the birds though.  If everything in the background above the brickline was blue sky I would have loved this one.</td>', 'There''s way too much going on in the background.  People on the bench looking this way, colorful dragons (or whatever), lots of lights, railings, umbrellas, and so on.  I wish all that stuff was out of focus, reducing them to oblivion.  Instead I just find them very distracting.  I love the kid and the birds though.  If everything in the background above the brickline was blue sky I would have loved this one.', '2011-03-29 01:08:02.000000', NULL, 1),
(6365924, 941892, 124256, '<td valign="top">The shot is far too dark.  The highlights on the palm on the right jump out as much or more than the subject and really detracts from the overall texture and feel of the photo.</td>', 'The shot is far too dark.  The highlights on the palm on the right jump out as much or more than the subject and really detracts from the overall texture and feel of the photo.', '2011-03-29 01:08:06.000000', NULL, 1),
(6365925, 942243, 124256, '<td valign="top">The way this shot is composed, the feeder is too dominant and fake looking, and I feel like something needs to be sharply in focus (though I can''t find something).  I bet if you cropped it to include just the bird on the left (and not the feeder, or at least the "building" part of it) that this would have done very well.  The colors and bokeh of the background are amazing.  I like the expression/action of the bird on the feeder, but not being in focus kills it for me.</td>', 'The way this shot is composed, the feeder is too dominant and fake looking, and I feel like something needs to be sharply in focus (though I can''t find something).  I bet if you cropped it to include just the bird on the left (and not the feeder, or at least the "building" part of it) that this would have done very well.  The colors and bokeh of the background are amazing.  I like the expression/action of the bird on the feeder, but not being in focus kills it for me.', '2011-03-29 01:10:49.000000', NULL, 1),
(6365926, 942287, 124256, '<td valign="top">It''s just too washed out, and to me the bird is too small (I suggest a tighter crop).</td>', 'It''s just too washed out, and to me the bird is too small (I suggest a tighter crop).', '2011-03-29 01:11:32.000000', NULL, 1),
(6365927, 942238, 124256, '<td valign="top">Neat, but I don''t get the pose.  It would have helped a lot to see the head.</td>', 'Neat, but I don''t get the pose.  It would have helped a lot to see the head.', '2011-03-29 01:12:06.000000', NULL, 1),
(6365928, 941124, 124256, '<td valign="top">Neat, but I wish I could see the head.  It doesn''t pop.</td>', 'Neat, but I wish I could see the head.  It doesn''t pop.', '2011-03-29 01:12:33.000000', NULL, 1),
(6365929, 941126, 124256, '<td valign="top">Too bad the ugly building was right behind the bird.  I feel like the shot needs to at least be straightened out, the building isn''t compelling enough to work at an angle.  It seems like the bird isn''t in focus.</td>', 'Too bad the ugly building was right behind the bird.  I feel like the shot needs to at least be straightened out, the building isn''t compelling enough to work at an angle.  It seems like the bird isn''t in focus.', '2011-03-29 01:13:43.000000', NULL, 1),
(6365932, 941735, 124256, '<td valign="top">Neat.  I don''t think I like the color of the sky, and for me the placement of the subject neatly in the corner doesn''t work.</td>', 'Neat.  I don''t think I like the color of the sky, and for me the placement of the subject neatly in the corner doesn''t work.', '2011-03-29 01:14:33.000000', NULL, 1),
(6365933, 942253, 124256, '<td valign="top">This is great in bw.  I like the contrast and framing.</td>', 'This is great in bw.  I like the contrast and framing.', '2011-03-29 01:15:25.000000', NULL, 1),
(6365934, 941821, 124256, '<td valign="top">I love the idea here.  The pattern of the iridescence just turns out to be far to distracting and manufactured looking (perhaps because it was an aggressive crop on the original).  That said, I think I would have liked this much more if you just cropped this much more tightly around the bird.  The iridescence is just far too dominant and seems to be the subject of the photo.</td>', 'I love the idea here.  The pattern of the iridescence just turns out to be far to distracting and manufactured looking (perhaps because it was an aggressive crop on the original).  That said, I think I would have liked this much more if you just cropped this much more tightly around the bird.  The iridescence is just far too dominant and seems to be the subject of the photo.', '2011-03-29 01:15:40.000000', NULL, 1),
(6365936, 941997, 124256, '<td valign="top">It seems like the only color comes from the out of focus leaves in the foreground.  As is I think it would be better in bw.  In color, I feel like at least the sky needs to have some color or texture.</td>', 'It seems like the only color comes from the out of focus leaves in the foreground.  As is I think it would be better in bw.  In color, I feel like at least the sky needs to have some color or texture.', '2011-03-29 01:17:39.000000', NULL, 1),
(6365937, 941802, 124256, '<td valign="top">Nice shot.  It doesn''t seem to have oomph.  I get the feeling that the scale of the cropping is between two sweet spots (too small or too large).</td>', 'Nice shot.  It doesn''t seem to have oomph.  I get the feeling that the scale of the cropping is between two sweet spots (too small or too large).', '2011-03-29 01:17:43.000000', NULL, 1),
(6365938, 942281, 124256, '<td valign="top">I wish the lone gull up in the sky was sharply in focus.  I think that would have really helped this shot pop.</td>', 'I wish the lone gull up in the sky was sharply in focus.  I think that would have really helped this shot pop.', '2011-03-29 01:18:30.000000', NULL, 1),
(6365939, 942265, 124256, '<td valign="top">Something about the building (or whatever the structure is) really detracts from this shot for me.  I wish I either saw less of it or not at all.</td>', 'Something about the building (or whatever the structure is) really detracts from this shot for me.  I wish I either saw less of it or not at all.', '2011-03-29 01:18:34.000000', NULL, 1),
(6365975, 941437, 114285, '<td valign="top">Now I''m wondering if this is you Vawendy, as I know you want to win a ribbon with a seagull. anyway very good wing span you got here. 9</td>', 'Now I''m wondering if this is you Vawendy, as I know you want to win a ribbon with a seagull. anyway very good wing span you got here. 9', '2011-03-29 02:27:51.000000', NULL, 1),
(6365976, 941220, 114285, '<td valign="top">Excellent one of the best, and probably ribbon for you. 10</td>', 'Excellent one of the best, and probably ribbon for you. 10', '2011-03-29 02:28:38.000000', NULL, 1),
(6365978, 941807, 114285, '<td valign="top">Oh this is adorable, reminds me of Nightpixels urban nature shot, ribbon for sure. 10</td>', 'Oh this is adorable, reminds me of Nightpixels urban nature shot, ribbon for sure. 10', '2011-03-29 02:31:52.000000', NULL, 1),
(6365979, 942265, 114285, '<td valign="top">I like this shot, nice comp.</td>', 'I like this shot, nice comp.', '2011-03-29 02:32:27.000000', NULL, 1),
(6366036, 941083, 29727, '<td valign="top">Beautiful</td>', 'Beautiful', '2011-03-29 06:40:30.000000', NULL, 1),
(6366082, 941869, 116631, '<td valign="top">I would have preferred if the bird and shadow weren''t cropped off the edge....</td>', 'I would have preferred if the bird and shadow weren''t cropped off the edge....', '2011-03-29 08:38:56.000000', NULL, 1),
(6366083, 942128, 116631, '<td valign="top">lol!!</td>', 'lol!!', '2011-03-29 08:40:09.000000', NULL, 1),
(6366133, 942128, 11769, '<td valign="top">Lyrical</td>', 'Lyrical', '2011-03-29 11:04:08.000000', NULL, 1),
(6366136, 941083, 11769, '<td valign="top">The darkness and composition with the pigeon stuffed into the lower left corner gives me the feeling of possible danger lurking just out of sight. Beautiful camera work.</td>', 'The darkness and composition with the pigeon stuffed into the lower left corner gives me the feeling of possible danger lurking just out of sight. Beautiful camera work.', '2011-03-29 11:09:34.000000', NULL, 1),
(6366143, 941807, 11769, '<td valign="top">Nice catch and love the ominous bokeh.</td>', 'Nice catch and love the ominous bokeh.', '2011-03-29 11:13:34.000000', NULL, 1),
(6366144, 941070, 11769, '<td valign="top">Love the blur</td>', 'Love the blur', '2011-03-29 11:14:19.000000', NULL, 1),
(6366145, 941821, 11769, '<td valign="top">Full spectrum</td>', 'Full spectrum', '2011-03-29 11:15:47.000000', NULL, 1),
(6366146, 941988, 11769, '<td valign="top">I''d swear that pigeon on the right is looking at me and saying the title.</td>', 'I''d swear that pigeon on the right is looking at me and saying the title.', '2011-03-29 11:17:24.000000', NULL, 1),
(6366148, 941660, 11769, '<td valign="top">These old buildings sure make a dramatic backdrop. They look like they are dancing.</td>', 'These old buildings sure make a dramatic backdrop. They look like they are dancing.', '2011-03-29 11:19:39.000000', NULL, 1),
(6366150, 942238, 11769, '<td valign="top">Looks like that bird is on a snowboard.</td>', 'Looks like that bird is on a snowboard.', '2011-03-29 11:20:40.000000', NULL, 1),
(6366151, 942095, 11769, '<td valign="top">nice</td>', 'nice', '2011-03-29 11:21:42.000000', NULL, 1),
(6366153, 942242, 11769, '<td valign="top">Love all the ones standing at the lower right. That is an amazing amount of birds in flight.</td>', 'Love all the ones standing at the lower right. That is an amazing amount of birds in flight.', '2011-03-29 11:24:58.000000', NULL, 1),
(6366251, 942219, 124256, '<td valign="top">The bird and shadow are gorgeous.  Lighting is perfect.  I don''t know what the weird rectangular areas are on the sand, but they seem out of place and distracting.</td>', 'The bird and shadow are gorgeous.  Lighting is perfect.  I don''t know what the weird rectangular areas are on the sand, but they seem out of place and distracting.', '2011-03-29 13:59:14.000000', NULL, 1),
(6366260, 942316, 13743, '<td valign="top">My eyes were drawn to the sunset and it took me a while to find the bird.</td>', 'My eyes were drawn to the sunset and it took me a while to find the bird.', '2011-03-29 14:09:20.000000', NULL, 1),
(6366298, 941126, 129427, '<td valign="top"><strike><u><b>The photo is good.. i like how it shows one thing only.. but theres too much space.. but its a aewsome photo </b></u></strike></td>', 'The photo is good.. i like how it shows one thing only.. but theres too much space.. but its a aewsome photo ', '2011-03-29 16:39:29.000000', NULL, 1),
(6366334, 942242, 47470, '<td valign="top">That''s an impressive number of birds.  Unfortunately, since they are each so small in the frame and they don''t have the benefit of color to help separate them from the background, they end up looking more like a texture.  That''s not necessarily a bad thing, in the bigger scope of things, but for this challenge, I don''t think it all works as well as it would have in color.  It''s a nice black and white conversion, though.</td>', 'That''s an impressive number of birds.  Unfortunately, since they are each so small in the frame and they don''t have the benefit of color to help separate them from the background, they end up looking more like a texture.  That''s not necessarily a bad thing, in the bigger scope of things, but for this challenge, I don''t think it all works as well as it would have in color.  It''s a nice black and white conversion, though.', '2011-03-29 17:58:10.000000', NULL, 1),
(6366335, 941083, 47470, '<td valign="top">This wouldn''t have worked nearly as well in color.</td>', 'This wouldn''t have worked nearly as well in color.', '2011-03-29 17:59:29.000000', NULL, 1),
(6366390, 941443, 97225, '<td valign="top">Beautiful image. I love the softness.</td>', 'Beautiful image. I love the softness.', '2011-03-29 19:28:07.000000', NULL, 1),
(6366391, 942248, 97225, '<td valign="top">Beautifully captured.</td>', 'Beautifully captured.', '2011-03-29 19:28:37.000000', NULL, 1),
(6366392, 941933, 97225, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2011-03-29 19:29:09.000000', NULL, 1),
(6366394, 941927, 97225, '<td valign="top">Brilliant capture, hilarious image.</td>', 'Brilliant capture, hilarious image.', '2011-03-29 19:29:54.000000', NULL, 1),
(6366395, 941395, 97225, '<td valign="top">Great capture - one of my two top picks. 10</td>', 'Great capture - one of my two top picks. 10', '2011-03-29 19:31:02.000000', NULL, 1),
(6366399, 941565, 54446, '<td valign="top">Best of challenge, by far.  Added to my favs.</td>', 'Best of challenge, by far.  Added to my favs.', '2011-03-29 19:32:21.000000', NULL, 1),
(6366419, 941739, 65234, '<td valign="top">Not the clearest capture in the world (through glass?) but amazing poses and I love their little shadows.</td>', 'Not the clearest capture in the world (through glass?) but amazing poses and I love their little shadows.', '2011-03-29 20:18:49.000000', NULL, 1),
(6366420, 942164, 65234, '<td valign="top">Definite sense of motion to this one and I like the green of the background whizzing by.</td>', 'Definite sense of motion to this one and I like the green of the background whizzing by.', '2011-03-29 20:19:40.000000', NULL, 1),
(6366423, 941129, 65234, '<td valign="top">Not a huge fan of the oversatured colors; sorry.</td>', 'Not a huge fan of the oversatured colors; sorry.', '2011-03-29 20:21:04.000000', NULL, 1),
(6366424, 942172, 65234, '<td valign="top">I don''t mind the motion blur in the wings but I wish the head was sharper and showed some detail.  It looks very dark on my screen.</td>', 'I don''t mind the motion blur in the wings but I wish the head was sharper and showed some detail.  It looks very dark on my screen.', '2011-03-29 20:21:56.000000', NULL, 1),
(6366425, 942066, 65234, '<td valign="top">I would love to see something like this in person.  Beautifully colorful birds, but unfortunately none are very sharp.</td>', 'I would love to see something like this in person.  Beautifully colorful birds, but unfortunately none are very sharp.', '2011-03-29 20:23:17.000000', NULL, 1),
(6366426, 941126, 65234, '<td valign="top">Nice catchlight in the eye; not easy in a flight shot.  Not a huge fan of the buildings and bit of tree in the background, though.  I think I would have waited till the bird flew higher, or tried to position myself lower, to get just sky in the background for this one.</td>', 'Nice catchlight in the eye; not easy in a flight shot.  Not a huge fan of the buildings and bit of tree in the background, though.  I think I would have waited till the bird flew higher, or tried to position myself lower, to get just sky in the background for this one.', '2011-03-29 20:25:27.000000', NULL, 1),
(6366549, 941518, 40391, '<td valign="top">Perfect timing!  I quite like the abstractness of the reflection too.  For me this may have been slightly over-sharpened with some haloing around the beak and legs.  But this doesnt take much away from the image which was one of my equal highest votes for this challenge.  Well done!</td>', 'Perfect timing!  I quite like the abstractness of the reflection too.  For me this may have been slightly over-sharpened with some haloing around the beak and legs.  But this doesnt take much away from the image which was one of my equal highest votes for this challenge.  Well done!', '2011-03-29 22:22:51.000000', NULL, 1),
(6366556, 941565, 40391, '<td valign="top">This is such a beautiful image.  It was obviously aware of your presence and the pose is wonderful.  However, its the high key effect that makes this one of my top picks.  Well done!</td>', 'This is such a beautiful image.  It was obviously aware of your presence and the pose is wonderful.  However, its the high key effect that makes this one of my top picks.  Well done!', '2011-03-29 22:25:24.000000', NULL, 1),
(6366561, 941807, 40391, '<td valign="top">Ive come back several times to this image as it really appeals to me.  I love the composition and timing of the image but its the grainy, dark bokeh that adds that extra emotional connection for me.  I love it and bumping to a 9.</td>', 'Ive come back several times to this image as it really appeals to me.  I love the composition and timing of the image but its the grainy, dark bokeh that adds that extra emotional connection for me.  I love it and bumping to a 9.', '2011-03-29 22:28:08.000000', NULL, 1),
(6366562, 941821, 40391, '<td valign="top">This image grabs my attention and imagination in a wonderful way.</td>', 'This image grabs my attention and imagination in a wonderful way.', '2011-03-29 22:29:08.000000', NULL, 1),
(6366569, 941220, 40391, '<td valign="top">Such a beautiful image!  You have done very well to produce such a great contrast from a very similar coloured background.</td>', 'Such a beautiful image!  You have done very well to produce such a great contrast from a very similar coloured background.', '2011-03-29 22:31:15.000000', NULL, 1),
(6366571, 941083, 40391, '<td valign="top">This lovely and poetic image evokes wonderful emotions for me.  Well done!</td>', 'This lovely and poetic image evokes wonderful emotions for me.  Well done!', '2011-03-29 22:32:14.000000', NULL, 1),
(6366572, 942013, 40391, '<td valign="top">Great capture  interesting background too (sort of appropriate for the unfortunate critter)</td>', 'Great capture  interesting background too (sort of appropriate for the unfortunate critter)', '2011-03-29 22:33:42.000000', NULL, 1),
(6366573, 941988, 40391, '<td valign="top">I feel this bird is conducting a hidden orchestra.  A lovely image that works very well in B&amp;W.</td>', 'I feel this bird is conducting a hidden orchestra.  A lovely image that works very well in B&W.', '2011-03-29 22:35:12.000000', NULL, 1),
