(6367563, 941009, 124815, '<td valign="top">Genesis 8:8 "Also He sent forth a dove from him, to see if the waters were abated from off the face of the ground"</td>', 'Genesis 8:8 "Also He sent forth a dove from him, to see if the waters were abated from off the face of the ground"', '2011-03-30 12:09:18.000000', NULL, 0),
(6367572, 941220, 20608, '<td valign="top">Someone''s on a roll</td>', 'Someone''s on a roll', '2011-03-30 12:14:20.000000', NULL, 0),
(6367578, 942284, 67152, '<td valign="top">It looks like a well worn bird.  The choice of f29 is very interesting when trying to capture birds.  I think you probably could have opened the aperture a bit more (f8 or so) and you would have been able to blur the background a bit more.   A bit better lighting on the face and a bit tighter crop and you would have have something special here.</td>', 'It looks like a well worn bird.  The choice of f29 is very interesting when trying to capture birds.  I think you probably could have opened the aperture a bit more (f8 or so) and you would have been able to blur the background a bit more.   A bit better lighting on the face and a bit tighter crop and you would have have something special here.', '2011-03-30 12:16:50.000000', NULL, 0),
(6367594, 941220, 67152, '<td valign="top">Beautiful work Sandy!  Congrats on a great image and on the ribbon too!</td>', 'Beautiful work Sandy!  Congrats on a great image and on the ribbon too!', '2011-03-30 12:25:37.000000', NULL, 0),
(6367595, 941022, 124815, '<td valign="top">....."but the dove found no place to set her foot, and she returned to him to the ark, for the waters were still on the face of the whole earth." (Genesis 8) - spectacular!</td>', '....."but the dove found no place to set her foot, and she returned to him to the ark, for the waters were still on the face of the whole earth." (Genesis 8) - spectacular!', '2011-03-30 12:25:46.000000', NULL, 0),
(6367597, 941220, 65319, '<td valign="top">Not surprisingly...this bird became one of my instant 10''s.  Your usual outstanding work, Sandy!</td>', 'Not surprisingly...this bird became one of my instant 10''s.  Your usual outstanding work, Sandy!', '2011-03-30 12:26:02.000000', NULL, 0),
(6367603, 942018, 65319, '<td valign="top">Congrats on your ribbon!  I thought this one might place higher...I just love the peli''s so much!  Well done!</td>', 'Congrats on your ribbon!  I thought this one might place higher...I just love the peli''s so much!  Well done!', '2011-03-30 12:28:48.000000', NULL, 0),
