INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6367667, 941220, 86447, '<td valign="top">It''s wonderful to see you on the podium, Sandy!   Congrats!</td>', 'It''s wonderful to see you on the podium, Sandy!   Congrats!', '2011-03-30 13:03:21.000000', NULL, 0),
(6367668, 942284, 129091, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by bassbone:</b></div><hr/><i> It looks like a well worn bird.  The choice of f29 is very interesting when trying to capture birds.  I think you probably could have opened the aperture a bit more (f8 or so) and you would have been able to blur the background a bit more.   A bit better lighting on the face and a bit tighter crop and you would have have something special here. </i></td></tr></table> <br/> <br/>Thanks for the feedback...I''m new to bird shooting and I was having a difficult time getting the bird sharp...hence is probably why I upped the aperature...I''m sure I was not thinking it through at the time.  I should have upped my shutter speed.  I have since went out and tried again...I see some improvement.  I will continue to work on this so I''m ready for the next bird challenge.<br/> <br/>Thank you for your feedback I really appreciate it!</td>', 'Originally posted by bassbone: It looks like a well worn bird.  The choice of f29 is very interesting when trying to capture birds.  I think you probably could have opened the aperture a bit more (f8 or so) and you would have been able to blur the background a bit more.   A bit better lighting on the face and a bit tighter crop and you would have have something special here.   Thanks for the feedback...I''m new to bird shooting and I was having a difficult time getting the bird sharp...hence is probably why I upped the aperature...I''m sure I was not thinking it through at the time.  I should have upped my shutter speed.  I have since went out and tried again...I see some improvement.  I will continue to work on this so I''m ready for the next bird challenge. Thank you for your feedback I really appreciate it!', '2011-03-30 13:03:33.000000', NULL, 0),
(6367669, 942018, 86447, '<td valign="top">One of my top faves...   Congrats on your ribbon!</td>', 'One of my top faves...   Congrats on your ribbon!', '2011-03-30 13:04:04.000000', NULL, 0),
(6367670, 941220, 43156, '<td valign="top">Great shot and great finish! Congrats with well deserved red!</td>', 'Great shot and great finish! Congrats with well deserved red!', '2011-03-30 13:04:11.000000', NULL, 0),
